-- Cập nhật nội dung theo CV (Rada360, AI360, Template Market, học vấn, TOEIC, SĐT, GitHub)
-- và viết lại phần giới thiệu. Chạy trong Supabase SQL Editor, rồi vào /admin bấm "Lưu & xuất bản".
-- Ghi đè toàn bộ hàng en, vi, profile bằng bản đọc lúc 2026-11-20: sửa gì trong /admin sau ngày đó sẽ mất.

update public.site_content set data = '{"cv": {"skills": "Skills", "profile": "Profile", "projects": "Projects", "education": "Education", "experience": "Experience"}, "ui": {"nav": "Main", "copy": "Copy email", "menu": "Menu", "close": "Close", "copied": "Copied", "toDark": "Switch to dark theme", "toLight": "Switch to light theme", "language": "Language", "backToTop": "Back to top"}, "nav": {"work": "Work", "about": "About", "stack": "Stack", "contact": "Contact", "experience": "Experience"}, "hero": {"role": "Frontend developer", "intro": "I build frontends at Foxscore. Before that I spent over a year as a fullstack developer at Rada360, writing both the Next.js UI and the Laravel API for an AI chatbot platform.", "stack": ["React", "Vue", "Next.js", "Nuxt.js", "TypeScript", "JavaScript", "Tailwind CSS", "AI coding agents", "REST APIs", "Laravel", "MySQL", "Docker", "Git"], "status": "Open to new roles and projects", "primary": "Get in touch", "secondary": "Download CV"}, "name": "Phạm Hồng Quân", "about": {"body": ["Since Feb 2026 I''ve been a frontend developer at Foxscore.", "At Rada360 I built an admin CMS with Laravel 12 and Next.js, then moved to AI360: a chatbot that answers customers on Zalo, Messenger and Telegram. I wired up each platform''s API, put the webhooks on queues and built the admin panel in Filament.", "On the side I make small tools that run entirely in the browser (reordering and signing PDFs, converting images) and a template marketplace in Laravel and Next.js."], "lead": "A year and a bit of fullstack, now focused on the frontend.", "stats": [{"label": "Years building production web apps", "value": 2}, {"label": "Products shipped to real users", "value": 2}], "title": "About", "principles": [{"title": "Build every state", "text": "A Figma file usually shows the happy path. I add loading, errors, empty lists and keyboard focus."}, {"title": "Measure before fixing", "text": "This portfolio used to stutter on old laptops. I measured each frame to find where the time went, then added a lighter mode that turns on when a machine can''t keep up."}, {"title": "Don''t ship a broken file", "text": "Folio and the PDF signer read back the file they export and compare it with the original. One page off and the download is blocked."}, {"title": "AI agents, my own review", "text": "I hand scaffolding and refactors to AI coding agents, then read every change myself before merging."}], "principlesTitle": "How I work"}, "stack": {"intro": "Frontend is the main job. I spent over a year on the backend, so I can still write the API when a feature needs it.", "title": "Where I work in the stack", "layers": [{"name": "Interface", "text": "Responsive, accessible pages built from Figma with React, Next.js and Tailwind CSS, with the animation and states that make them feel finished.", "level": "Main focus", "tools": ["React", "Next.js", "TypeScript", "Tailwind CSS"]}, {"name": "API", "text": "Integrating REST APIs on the client, and building them in Laravel when a feature needs it, with auth and Swagger docs.", "level": "Comfortable", "tools": ["REST", "Laravel", "Swagger", "Postman"]}, {"name": "Async", "text": "Webhooks from Zalo OA, Messenger and Telegram at AI360, processed on queues, so I know what the UI should show while the server is still busy.", "level": "Familiar", "tools": ["Webhooks", "Queues"]}, {"name": "Data", "text": "MySQL schemas and queries, enough to read a slow endpoint and know whether the fix belongs in the query or the UI.", "level": "Familiar", "tools": ["MySQL", "Docker"]}]}, "footer": {"rights": "All rights reserved.", "tagline": "Frontend developer in Ho Chi Minh City."}, "contact": {"lead": "Tell me about the role or the project. I usually reply within a day.", "title": "Have an interface that needs building?", "labels": {"phone": "Phone", "location": "Location"}, "location": "Ho Chi Minh City, Vietnam"}, "weather": {"kinds": {"fog": "Foggy", "rain": "Rain", "snow": "Snow", "clear": "Clear", "storm": "Thunderstorm", "cloudy": "Cloudy", "drizzle": "Drizzle"}, "fallbackCity": "Ho Chi Minh City"}, "projects": {"back": "Back to work", "next": "Next project", "prev": "Previous project", "intro": "Production products I''ve built or contributed to.", "items": [{"url": "https://hongquan-folio.vercel.app", "kind": "PDF page organizer", "name": "Folio", "year": "2026", "stack": ["React", "TypeScript", "pdf-lib", "pdf.js", "Tailwind CSS"], "study": {"did": ["Open several PDFs, drag whole groups of pages to reorder, rotate, delete, undo and redo with shortcuts", "Copy pages intact with pdf-lib: content streams, fonts and images keep their bytes, nothing is re-rendered as images", "Verify every exported page against the original (content, text, size, rotation) and block the download on any difference", "Download files embedded in the PDF as-is, such as e-invoice XML", "Mobile layout with bottom sheets and back-button handling; two UI themes that switch without losing the open document"], "role": "Design and development", "context": "A supermarket cashier needs to merge and reorder pages from several invoice PDFs without altering their content, and without uploading them to a server.", "outcome": "In real use for sorting invoices; everything runs in the browser, with no server or database."}, "description": "Reorder, rotate and delete PDF pages right in the browser, built for a supermarket cashier. Files never leave the device, pages are copied byte for byte and checked before download."}, {"url": "https://hongquan-pixform.vercel.app", "kind": "Image converter", "name": "Pixform", "year": "2026", "stack": ["React", "TypeScript", "WebAssembly", "Vite"], "study": {"did": ["Detect the real format from magic bytes and flag files whose extension lies about their content", "Read PNG, JPEG, WebP, AVIF, GIF, BMP, ICO, TIFF, HEIC and SVG; write 8 formats with quality and background controls", "Use the browser''s encoders and fall back to WebAssembly encoders where WebP or AVIF isn''t supported", "Load heavy codecs (HEIC, AVIF, TIFF) only when needed; show size before and after, download one by one or as a ZIP"], "role": "Design and development", "context": "Converting an image usually means uploading it to some unknown website. Pixform does it on the user''s own device, iPhone HEIC photos included.", "outcome": "Runs entirely in the browser; images are never uploaded."}, "description": "Batch-convert images between PNG, JPEG, WebP, AVIF, GIF, BMP, ICO and TIFF in the browser, detecting each file''s real format and downloading them as a ZIP."}, {"url": "https://hongquan-signature.vercel.app", "kind": "PDF signing in the browser", "name": "Signature", "year": "2026", "stack": ["React", "TypeScript", "pdf-lib", "pdf.js", "Vitest"], "study": {"did": ["Draw a signature on screen and place the signature, the full name or both; drag to move, rotate and resize", "Match page frames and rotation between pdf.js (display) and pdf-lib (writing), ignoring stray taps and extra fingers", "Render Vietnamese names as images, since pdf-lib''s standard fonts can''t encode the diacritics", "Re-read the signed file and check page count, sizes, original content and signature count before allowing the download", "On phones, share the signed file straight through the system share sheet"], "role": "Design and development", "context": "Sign a PDF quickly on a phone or laptop without installing an app or uploading the document to a third-party service.", "outcome": "An image signature, not a certificate-based digital signature; geometry and signing are covered by Vitest tests."}, "description": "Draw a handwritten signature with a finger, mouse or pen and place it anywhere in a PDF. Original content stays byte for byte, and the file never leaves the device."}, {"name": "Template Market", "kind": "Template marketplace", "year": "2026", "description": "Publish, share and sell templates: a Laravel 12 API, a Next.js frontend, files stored on AWS S3.", "stack": ["Next.js", "TypeScript", "TanStack Query", "Zustand", "Laravel", "MySQL", "AWS S3"], "url": "https://github.com/PhamHongQuan/Template-Market", "study": {"role": "Fullstack, personal project", "context": "A marketplace where people manage, share and buy templates, with a cart and orders.", "did": ["Laravel 12 API with Controller – Service – Repository, MySQL with Eloquent relations", "Next.js, React and TypeScript frontend; Axios with TanStack Query for data, Zustand for state", "JWT auth; templates, categories, cart, orders and user profiles", "Thumbnail, preview and source uploads to AWS S3", "Docker for the dev environment, Swagger for API docs"], "outcome": "In progress. Source on GitHub."}}, {"url": "https://rada360.com", "kind": "Booking system", "name": "Rada360", "year": "2025", "stack": ["Next.js", "React", "TypeScript", "Tailwind CSS", "Laravel"], "study": {"did": ["Turned the Figma designs into responsive booking pages with Next.js, React, TypeScript and Tailwind CSS", "Wired the pages to the APIs for services, time slots and bookings with Axios", "Built the admin CMS in Laravel 12 with Controller – Service – Repository: CRUD, validation, search, filters, pagination", "Designed the MySQL tables and Eloquent relations; documented and tested the API with Swagger and Postman"], "role": "Frontend and API developer", "context": "A booking system: customers pick a service, choose a free time slot and book it.", "outcome": "In production at rada360.com, used by real customers."}, "description": "Booking pages and an admin CMS: a Next.js, React and TypeScript frontend on a Laravel 12 API."}, {"url": "https://ai.rada360.com", "kind": "SaaS AI chatbot platform", "name": "AI360", "year": "2025", "stack": ["Laravel", "Filament", "MySQL", "Queue", "Tailwind CSS"], "study": {"did": ["Built a layered REST API with a service layer that keeps business logic out of controllers", "Integrated the AI Core API for chatbot training and conversation flows", "Connected Zalo Official Account, Facebook Messenger and the Telegram Bot API so the bot receives and answers messages", "Moved webhook handling and outgoing messages onto queues, cutting response times", "Admin panel in Filament; Google OAuth and reCAPTCHA; a referral program"], "role": "Fullstack developer", "context": "A SaaS platform for AI chatbots that answer customers on Facebook, Zalo, Telegram and websites.", "outcome": "Live at ai.rada360.com."}, "description": "An AI chatbot that answers customers on Zalo, Messenger, Telegram and websites: REST API, Filament admin, webhooks on queues."}], "title": "Selected work", "visit": "Visit site", "labels": {"did": "What I did", "role": "Role", "year": "Year", "stack": "Stack", "context": "Context", "outcome": "Outcome"}, "caseStudy": "Case study"}, "experience": {"jobs": [{"org": "Foxscore", "meta": "Full-time, Ho Chi Minh City", "role": "Frontend Developer", "stack": [], "period": "Feb 2026 – Present", "points": []}, {"org": "Rada360 Technology JSC", "meta": "Full-time, Ho Chi Minh City", "role": "Fullstack Developer", "stack": ["Next.js", "React", "TypeScript", "Tailwind CSS", "Laravel", "MySQL", "Filament", "Docker"], "period": "Dec 2024 – Feb 2026", "points": ["Rada360: admin CMS in Laravel 12 with Controller – Service – Repository, and a Next.js, React and TypeScript UI with search, filters and pagination", "AI360: REST API for the chatbot platform, an admin panel in Filament, and an AI Core API integration for conversation flows", "Connected the chatbot to Zalo Official Account, Facebook Messenger and Telegram; webhooks and outgoing messages run on queues", "Google OAuth sign-in and reCAPTCHA against spam", "Worked with BA and QA from requirements through testing and release; documented APIs in Swagger, ran dev environments in Docker"]}], "intro": "Where I''ve worked and what I did there.", "title": "Experience", "education": [{"org": "Nong Lam University, Ho Chi Minh City", "note": "GPA 3.25 / 4. ReactJS, Java (Spring Boot), PHP (Laravel), database systems.", "title": "Information Technology", "period": "Sep 2021 – May 2026"}, {"org": "IIG Vietnam", "note": "Comfortable reading English technical documentation.", "title": "TOEIC 590", "period": "Sep 2024"}], "stackLabel": "Stack", "educationTitle": "Education"}}'::jsonb where key = 'en';
update public.site_content set data = '{"cv": {"skills": "Kỹ năng", "profile": "Giới thiệu", "projects": "Dự án", "education": "Học vấn", "experience": "Kinh nghiệm"}, "ui": {"nav": "Điều hướng", "copy": "Sao chép email", "menu": "Menu", "close": "Đóng", "copied": "Đã sao chép", "toDark": "Chuyển sang giao diện tối", "toLight": "Chuyển sang giao diện sáng", "language": "Ngôn ngữ", "backToTop": "Lên đầu trang"}, "nav": {"work": "Dự án", "about": "Giới thiệu", "stack": "Thế mạnh", "contact": "Liên hệ", "experience": "Kinh nghiệm"}, "hero": {"role": "Lập trình viên Frontend", "intro": "Tôi làm frontend ở Foxscore. Trước đó tôi làm fullstack hơn một năm ở Rada360, viết cả giao diện Next.js lẫn API Laravel cho một nền tảng chatbot AI.", "stack": ["React", "Vue", "Next.js", "Nuxt.js", "TypeScript", "JavaScript", "Tailwind CSS", "AI coding agents", "REST APIs", "Laravel", "MySQL", "Docker", "Git"], "status": "Sẵn sàng cho vị trí và dự án mới", "primary": "Liên hệ với tôi", "secondary": "Tải CV"}, "name": "Phạm Hồng Quân", "about": {"body": ["Từ 02/2026 tôi làm frontend ở Foxscore.", "Ở Rada360 tôi làm trang quản trị bằng Laravel 12 và Next.js, rồi chuyển sang AI360: chatbot trả lời khách trên Zalo, Messenger và Telegram. Tôi nối API của từng nền tảng, đưa webhook vào queue và làm trang quản trị bằng Filament.", "Ngoài giờ tôi làm mấy công cụ chạy hoàn toàn trên trình duyệt (sắp xếp và ký PDF, đổi định dạng ảnh) và một marketplace template bằng Laravel và Next.js."], "lead": "Hơn một năm làm fullstack, giờ tập trung vào frontend.", "stats": [{"label": "Năm xây dựng ứng dụng web production", "value": 2}, {"label": "Sản phẩm đến tay người dùng thật", "value": 2}], "title": "Giới thiệu", "principles": [{"title": "Làm đủ các trạng thái", "text": "Bản Figma thường chỉ vẽ lúc mọi thứ ổn. Tôi làm thêm loading, lỗi, danh sách rỗng và focus bàn phím."}, {"title": "Đo rồi mới sửa", "text": "Portfolio này từng giật trên máy yếu. Tôi đo từng frame để tìm chỗ tốn thời gian, rồi thêm một bản nhẹ tự bật khi máy không kéo nổi."}, {"title": "Không để file sai lọt ra", "text": "Folio và Ký PDF đọc lại file xuất ra và so với file gốc. Lệch một trang là chặn tải."}, {"title": "Dùng AI agent, tự đọc diff", "text": "Tôi giao cho AI coding agent phần dựng khung và refactor, rồi tự đọc từng thay đổi trước khi merge."}], "principlesTitle": "Cách tôi làm việc"}, "stack": {"intro": "Frontend là việc chính. Backend tôi đã làm hơn một năm, nên vẫn tự viết API được khi cần.", "title": "Tôi mạnh ở tầng nào", "layers": [{"name": "Giao diện", "text": "Trang responsive, dễ tiếp cận dựng từ Figma với React, Next.js và Tailwind CSS, cùng animation và các trạng thái khiến giao diện trông hoàn thiện.", "level": "Thế mạnh chính", "tools": ["React", "Next.js", "TypeScript", "Tailwind CSS"]}, {"name": "API", "text": "Tích hợp REST API phía client, và tự viết bằng Laravel khi tính năng cần, có xác thực và tài liệu Swagger.", "level": "Thành thạo", "tools": ["REST", "Laravel", "Swagger", "Postman"]}, {"name": "Bất đồng bộ", "text": "Webhook từ Zalo OA, Messenger và Telegram ở AI360, xử lý qua queue, nên tôi biết giao diện nên hiển thị gì khi server còn đang xử lý.", "level": "Đã làm", "tools": ["Webhook", "Queue"]}, {"name": "Dữ liệu", "text": "Schema và truy vấn MySQL, đủ để đọc một endpoint chậm và biết nên sửa ở truy vấn hay ở giao diện.", "level": "Đã làm", "tools": ["MySQL", "Docker"]}]}, "footer": {"rights": "Bảo lưu mọi quyền.", "tagline": "Lập trình viên frontend ở TP. Hồ Chí Minh."}, "contact": {"lead": "Kể cho tôi về vị trí hoặc dự án. Tôi thường trả lời trong vòng một ngày.", "title": "Bạn cần dựng một giao diện?", "labels": {"phone": "Điện thoại", "location": "Địa điểm"}, "location": "TP. Hồ Chí Minh, Việt Nam"}, "weather": {"kinds": {"fog": "Sương mù", "rain": "Mưa", "snow": "Tuyết", "clear": "Trời quang", "storm": "Giông", "cloudy": "Nhiều mây", "drizzle": "Mưa phùn"}, "fallbackCity": "TP. Hồ Chí Minh"}, "projects": {"back": "Quay lại dự án", "next": "Dự án tiếp theo", "prev": "Dự án trước", "intro": "Những sản phẩm production tôi đã xây dựng hoặc tham gia.", "items": [{"url": "https://hongquan-folio.vercel.app", "kind": "Công cụ sắp xếp trang PDF", "name": "Folio", "year": "2026", "stack": ["React", "TypeScript", "pdf-lib", "pdf.js", "Tailwind CSS"], "study": {"did": ["Mở nhiều PDF, kéo thả cả nhóm trang để đổi thứ tự, xoay, xoá, hoàn tác/làm lại bằng phím tắt", "Chép trang nguyên vẹn bằng pdf-lib: content stream, font, ảnh giữ nguyên byte, không render lại thành ảnh", "Kiểm tra toàn vẹn từng trang của file xuất so với file gốc (nội dung, chữ, kích thước, góc xoay); sai lệch là chặn tải", "Tải nguyên bản file đính kèm trong PDF, ví dụ XML hoá đơn điện tử", "Giao diện mobile có bottom sheet, nút back đóng sheet; hai bộ giao diện chuyển qua lại không mất tài liệu"], "role": "Thiết kế và phát triển", "context": "Thủ quỹ siêu thị cần gộp và sắp xếp lại trang từ nhiều file PDF hoá đơn mà không được làm sai lệch nội dung, và không muốn tải file lên máy chủ.", "outcome": "Đang dùng thật cho việc sắp xếp hoá đơn; mọi xử lý chạy trên trình duyệt, không có máy chủ hay database."}, "description": "Sắp xếp, xoay, xoá trang PDF ngay trên trình duyệt cho thủ quỹ siêu thị. File không rời máy, trang được chép nguyên byte và tự kiểm tra trước khi cho tải."}, {"url": "https://hongquan-pixform.vercel.app", "kind": "Công cụ chuyển định dạng ảnh", "name": "Pixform", "year": "2026", "stack": ["React", "TypeScript", "WebAssembly", "Vite"], "study": {"did": ["Nhận diện định dạng thật bằng magic bytes, báo rõ khi đuôi file không khớp nội dung", "Đọc PNG, JPG, WebP, AVIF, GIF, BMP, ICO, TIFF, HEIC, SVG; ghi ra 8 định dạng, chỉnh chất lượng và màu nền", "Dùng encoder của trình duyệt, tự chuyển sang encoder WebAssembly khi trình duyệt không hỗ trợ WebP/AVIF", "Thư viện nặng (HEIC, AVIF, TIFF) chỉ tải khi cần; xem dung lượng trước/sau, tải từng file hoặc gộp ZIP"], "role": "Thiết kế và phát triển", "context": "Đổi định dạng ảnh thường phải tải ảnh lên một website lạ. Pixform làm việc đó ngay trên máy người dùng, kể cả ảnh HEIC từ iPhone.", "outcome": "Chạy hoàn toàn trên trình duyệt, ảnh không bị tải lên máy chủ."}, "description": "Chuyển hàng loạt ảnh giữa PNG, JPG, WebP, AVIF, GIF, BMP, ICO, TIFF ngay trên trình duyệt, tự nhận định dạng thật của file và tải về dạng ZIP."}, {"url": "https://hongquan-signature.vercel.app", "kind": "Ký PDF trên trình duyệt", "name": "Ký PDF", "year": "2026", "stack": ["React", "TypeScript", "pdf-lib", "pdf.js", "Vitest"], "study": {"did": ["Vẽ chữ ký trên màn hình, đặt chữ ký, họ tên hoặc cả hai lên trang; kéo để di chuyển, xoay, đổi cỡ", "Khớp khung trang và góc xoay giữa pdf.js (hiển thị) và pdf-lib (ghi), bỏ qua chạm nhầm và ngón tay thừa", "Vẽ họ tên tiếng Việt thành ảnh vì font chuẩn của pdf-lib không mã hoá được dấu", "Đọc lại file đã ký để kiểm tra số trang, kích thước, nội dung gốc và số chữ ký trước khi cho tải", "Trên điện thoại, chia sẻ file đã ký thẳng qua bảng chia sẻ của hệ điều hành"], "role": "Thiết kế và phát triển", "context": "Ký nhanh một file PDF trên điện thoại hay máy tính mà không cần cài app hay tải tài liệu lên dịch vụ bên ngoài.", "outcome": "Đây là chữ ký hình ảnh, không phải chữ ký số; phần hình học và ký có test bằng Vitest."}, "description": "Vẽ chữ ký tay bằng ngón tay, chuột hoặc bút rồi đặt lên một hay nhiều chỗ trong PDF. Nội dung gốc giữ nguyên từng byte, file không rời máy."}, {"name": "Template Market", "kind": "Marketplace template", "year": "2026", "description": "Nơi đăng, chia sẻ và mua bán template: Laravel 12 làm API, Next.js làm giao diện, file lưu trên AWS S3.", "stack": ["Next.js", "TypeScript", "TanStack Query", "Zustand", "Laravel", "MySQL", "AWS S3"], "url": "https://github.com/PhamHongQuan/Template-Market", "study": {"role": "Fullstack, dự án cá nhân", "context": "Một marketplace nơi người dùng quản lý, chia sẻ và mua bán template, có giỏ hàng và đơn hàng.", "did": ["API bằng Laravel 12 theo Controller – Service – Repository, MyS